import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
BATCHES = json.loads((ROOT / 'graphify-out/semantic-batches.json').read_text())
COVERAGE = []
RESULTS = []

class Fragment:
    def __init__(self, batch):
        self.batch = batch
        self.files = BATCHES[batch]
        self.nodes = []
        self.edges = []
        self.hyperedges = []
    def node(self, f, label, summary, location, kind='concept', rationale=None):
        source = self.files[f]
        stem = re.sub('[^a-z0-9]', '_', str(Path(source).relative_to(ROOT).with_suffix('')).lower())
        entity = re.sub('[^a-z0-9]', '_', label.lower()).strip('_')
        node_id = stem + '_' + entity
        n = dict(id=node_id, label=label, file_type=kind, source_file=source, source_location=location,
                 source_url=None, captured_at=None, author=None, contributor=None, summary=summary)
        text = Path(source).read_text()
        if text.startswith('---'):
            frontmatter = text.split('---', 2)[1]
            for field in ('source_url', 'captured_at', 'author', 'contributor'):
                match = re.search('^' + field + r':\s*(.+)$', frontmatter, re.M)
                if match:
                    n[field] = match.group(1).strip().strip('"\'')
        if rationale:
            n['rationale'] = rationale
        self.nodes.append(n)
        return node_id
    def edge(self, a, b, relation, f, location, inferred=False, rationale=None):
        e = dict(source=a, target=b, relation=relation, confidence='INFERRED' if inferred else 'EXTRACTED',
                 confidence_score=0.85 if inferred else 1.0, source_file=self.files[f], source_location=location, weight=1.0)
        if rationale:
            e['rationale'] = rationale
        self.edges.append(e)
    def group(self, f, label, summary, location, items):
        parent = self.node(f, label, summary, location)
        out = {'root': parent}
        for name, desc in items:
            out[name] = self.node(f, name, desc, location)
            self.edge(parent, out[name], 'references', f, location)
        return out
    def finish(self, special=None):
        special = special or {}
        ids = {n['id'] for n in self.nodes}
        assert len(ids) == len(self.nodes)
        assert all(e['source'] in ids and e['target'] in ids for e in self.edges)
        assert len(self.nodes) <= 150
        for f in self.files:
            nodes = [n for n in self.nodes if n['source_file'] == f]
            assert nodes, f
            detail = special.get(str(Path(f).relative_to(ROOT)), {})
            COVERAGE.append(dict(source_file=f, batch=self.batch+1, read=True, node_count=len(nodes),
                                 depth=detail.get('depth', 'full_document_concept_extraction'),
                                 limitations=detail.get('limitations', ['Static document evidence; source implementation and runtime behavior not verified.']),
                                 errors=[]))
        p = ROOT / f'graphify-out/.graphify_chunk_{self.batch+1:02d}.json'
        p.write_text(json.dumps(dict(nodes=self.nodes, edges=self.edges, hyperedges=self.hyperedges,
                                    input_tokens=0, output_tokens=0), ensure_ascii=False, indent=2))
        RESULTS.append(dict(path=str(p), nodes=len(self.nodes), edges=len(self.edges)))

